from lc import L, w, gr, q

B2 = [
 L("Our Moon: Closer Than You Think", "月球：比你想的更親近", [
   "The Moon is about 384,000 kilometers from Earth, close enough for light to cross the distance in just over a second. Scientists believe it formed around 4.5 billion years ago, probably after a huge object crashed into the young Earth and threw rock into space.",
   "Because the Moon spins at the same speed as it travels around us, we always see the same side. Its gravity pulls on the oceans and creates the tides, which rise and fall twice a day along most coasts.",
   "In 1969, Neil Armstrong became the first person to walk on its surface, and twelve astronauts in total have since followed in the Apollo program. Now space agencies are planning to send people back, with the long-term goal of building a permanent base there."],
  [w("distance","noun","/ˈdɪs.təns/","距離","the amount of space between two places","a long distance","cross the distance 跨越這段距離。"),
   w("crash","verb","/kræʃ/","撞擊","to hit something hard","The car crashed into a tree.","crash into + 名詞。"),
   w("spin","verb","/spɪn/","自轉、旋轉","to turn around quickly many times","The wheel spins fast.","spins 第三人稱單數。"),
   w("gravity","noun","/ˈɡræv.ə.t̬i/","重力、引力","the force that pulls things towards each other","Gravity keeps us on the ground.","不可數名詞。"),
   w("tide","noun","/taɪd/","潮汐","the regular rise and fall of the sea","high tide","the tides rise and fall 潮起潮落。"),
   w("surface","noun","/ˈsɝː.fəs/","表面","the outside or top layer of something","the surface of the water","walk on its surface 在它表面行走。"),
   w("permanent","adjective","/ˈpɝː.mə.nənt/","永久的","lasting for a long time or forever","a permanent job","a permanent base 永久基地。")],
  [gr("close enough for… to…","近到足以讓…。","close enough for light to cross the distance in just over a second"),
   gr("Because + 子句","說明原因。","Because the Moon spins at the same speed as it travels around us, we always see the same side."),
   gr("現在完成 have since followed","從那時起已經…。","twelve astronauts in total have since followed in the Apollo program")],
  [q("How did the Moon probably form?","After a huge object hit the young Earth","From a cloud of ice","It was captured from Mars"),
   q("Why do we always see the same side of the Moon?","It spins at the same speed as it orbits Earth","It does not move","Earth blocks the other side"),
   q("What is a long-term goal of space agencies?","Building a permanent base on the Moon","Moving the Moon","Stopping the tides")]),
 L("From Ethiopian Hills to Your Cup", "從衣索比亞山丘到你的杯子", [
   "According to a popular legend, coffee was discovered in Ethiopia when a goat herder noticed his animals becoming unusually lively after eating red berries. Whether or not the story is true, coffee drinking is first clearly recorded in Yemen in the 15th century.",
   "From there, coffeehouses spread across the Ottoman Empire and later to Europe, where they became lively places for news, debate and business. Today, coffee is one of the most widely traded farm products in the world, and Brazil is the largest producer.",
   "The beans we roast are actually the seeds of a fruit often called a coffee cherry. Most coffee comes from two types of plant, arabica and robusta. The caffeine in coffee makes us feel alert by blocking a chemical in the brain that builds up and makes us feel tired."],
  [w("legend","noun","/ˈledʒ.ənd/","傳說","an old story that may not be true","an ancient legend","According to a legend 根據傳說。"),
   w("lively","adjective","/ˈlaɪv.li/","活潑的、熱鬧的","full of energy","a lively party","becoming unusually lively 變得異常活潑。"),
   w("record","verb","/rɪˈkɔːrd/","記載","to write down information so it can be used later","The event was recorded in books.","be recorded 被記載。"),
   w("debate","noun","/dɪˈbeɪt/","辯論","a discussion where people give different opinions","a political debate","news, debate and business 新聞、辯論與生意。"),
   w("trade","verb","/treɪd/","買賣、交易","to buy and sell goods","Countries trade oil.","widely traded 廣泛交易的。"),
   w("roast","verb","/roʊst/","烘焙","to cook with dry heat","roast coffee beans","the beans we roast 我們烘的豆子。"),
   w("alert","adjective","/əˈlɝːt/","清醒的、警覺的","awake and able to think quickly","Coffee keeps me alert.","feel alert 感覺清醒。")],
  [gr("Whether or not…","不管…是否…。","Whether or not the story is true, coffee drinking is first clearly recorded in Yemen"),
   gr("關係副詞 where","where 指 Europe 的咖啡館。","later to Europe, where they became lively places for news, debate and business"),
   gr("by + V-ing","透過…的方式。","makes us feel alert by blocking a chemical in the brain")],
  [q("Where is coffee drinking first clearly recorded?","Yemen","Brazil","France"),
   q("What were European coffeehouses used for?","News, debate and business","Only sleeping","Selling goats"),
   q("How does caffeine make us feel alert?","By blocking a chemical that makes us tired","By adding sugar to the blood","By cooling the brain")]),
 L("Why Walking Is Underrated", "為什麼走路被低估了", [
   "Walking may be the simplest form of exercise there is. It needs no special equipment, costs nothing and can fit into almost any day. Yet many people underestimate how much good it can do.",
   "The famous target of 10,000 steps a day actually began as a slogan in a Japanese advertising campaign for pedometers in the 1960s. Research suggests that health benefits begin well below that number, and that every extra bit of movement helps.",
   "Regular walking strengthens the heart, helps control weight and can lift your mood. One study at Stanford University even found that people came up with more creative ideas while walking than while sitting. So next time you are stuck on a problem, try taking it for a walk."],
  [w("equipment","noun","/ɪˈkwɪp.mənt/","設備","the tools needed for an activity","sports equipment","不可數名詞，不加 s。"),
   w("fit","verb","/fɪt/","安排進、容納","to find time or space for something","I can fit you in at 3.","fit into + 名詞。"),
   w("underestimate","verb","/ˌʌn.dɚˈes.tə.meɪt/","低估","to think something is less important than it is","Don't underestimate her.","under- + estimate。"),
   w("slogan","noun","/ˈsloʊ.ɡən/","標語、口號","a short, easy phrase used in advertising","a catchy slogan","began as a slogan 一開始只是口號。"),
   w("campaign","noun","/kæmˈpeɪn/","活動、宣傳","planned activities to sell or achieve something","an advertising campaign","advertising campaign 廣告宣傳。"),
   w("benefit","noun","/ˈben.ə.fɪt/","好處","a good effect","the benefits of exercise","health benefits 健康益處。"),
   w("creative","adjective","/kriˈeɪ.t̬ɪv/","有創意的","producing new ideas","a creative solution","creative ideas 創意點子。")],
  [gr("the simplest… there is","世上最簡單的…（加強語氣）。","Walking may be the simplest form of exercise there is."),
   gr("well below","遠低於…。","health benefits begin well below that number"),
   gr("比較 more… while A than while B","在 A 時比在 B 時更…。","people came up with more creative ideas while walking than while sitting")],
  [q("Where did the 10,000-step target come from?","A Japanese advertising campaign","A medical law","An Olympic rule"),
   q("When do health benefits begin, according to research?","Well below 10,000 steps","Only above 20,000 steps","Only after a year"),
   q("What did the Stanford study find?","Walking boosted creative ideas","Sitting was more creative","Walking made people sleepy")]),
 L("Speaking So People Want to Listen", "說話讓人想聽", [
   "Sound expert Julian Treasure begins his TED talk with an interesting question: why do some people's words have more power than others? He believes that what we say and how we say it both matter.",
   "First, he lists seven bad habits that make people stop listening, including gossip, complaining, making excuses and exaggerating. As an alternative, he offers four foundations for powerful speech: honesty, authenticity, integrity and love.",
   "He then explains that the voice itself is a toolbox. We can change our tone, speed, pitch and volume to keep listeners interested. Even silence can be powerful when used at the right moment. He ends by showing the audience some warm-up exercises to prepare the voice before an important talk."],
  [w("expert","noun","/ˈek.spɝːt/","專家","a person with special knowledge","a sound expert","sound expert 聲音專家。"),
   w("gossip","noun","/ˈɡɑː.sɪp/","八卦、閒話","talk about other people's private lives","office gossip","不可數名詞。"),
   w("exaggerate","verb","/ɪɡˈzædʒ.ə.reɪt/","誇大","to say something is bigger or worse than it is","Don't exaggerate!","exaggerating 動名詞。"),
   w("alternative","noun","/ɑːlˈtɝː.nə.t̬ɪv/","替代方案","another choice","a healthy alternative","As an alternative 作為替代。"),
   w("integrity","noun","/ɪnˈteɡ.rə.t̬i/","正直","being honest and having strong moral principles","a man of integrity","不可數名詞。"),
   w("pitch","noun","/pɪtʃ/","音高","how high or low a sound is","a high pitch","tone, speed, pitch and volume 語調、速度、音高、音量。"),
   w("silence","noun","/ˈsaɪ.ləns/","沉默","complete quiet","a moment of silence","Even silence can be powerful 連沉默都有力量。")],
  [gr("what we say and how we say it","兩個名詞子句當主詞。","what we say and how we say it both matter"),
   gr("including + 名詞","列舉例子。","including gossip, complaining, making excuses and exaggerating"),
   gr("when used…","when (it is) used 省略主詞與 be。","Even silence can be powerful when used at the right moment.")],
  [q("What is Julian Treasure's profession?","Sound expert","Doctor","Chef"),
   q("Which is one of the four foundations he suggests?","Honesty","Gossip","Complaining"),
   q("What can the voice be compared to, according to him?","A toolbox","A machine gun","A painting")]),
]

C1 = [
 L("The Moon's Quiet Influence on Earth", "月球對地球默默的影響", [
   "Hanging some 384,000 kilometers away, the Moon can seem like little more than a decorative feature of the night sky. In fact, it is intimately bound up with Earth's history and present-day behavior.",
   "The prevailing theory holds that it coalesced around 4.5 billion years ago from debris thrown out when a Mars-sized body struck the infant Earth. Over time, tidal forces slowed its rotation until it became tidally locked, which is why the same hemisphere perpetually faces us.",
   "Those same forces govern the ocean tides, shaping coastal ecosystems and, over geological time, gradually lengthening our day. The Moon also helps stabilize the tilt of Earth's axis, which some scientists believe has kept our climate more stable than it might otherwise have been.",
   "Only twelve people, all Apollo astronauts between 1969 and 1972, have ever set foot there. Yet after a half-century hiatus, the Moon is back on the agenda, with space agencies now aiming to return crews and, eventually, to establish a sustained presence on its surface."],
  [w("intimately","adverb","/ˈɪn.t̬ə.mət.li/","密切地","in a very close way","intimately connected","be intimately bound up with… 與…密切相關。"),
   w("prevailing","adjective","/prɪˈveɪ.lɪŋ/","主流的、盛行的","most common or accepted at a time","the prevailing view","the prevailing theory 主流理論。"),
   w("coalesce","verb","/ˌkoʊ.əˈles/","聚合","to come together to form one mass","Ideas coalesced into a plan.","coalesce from… 由…聚合而成。"),
   w("debris","noun","/dəˈbriː/","碎片、殘骸","broken pieces left after something is destroyed","space debris","不可數名詞。"),
   w("perpetually","adverb","/pɚˈpetʃ.u.ə.li/","永久地、不斷地","all the time; forever","perpetually busy","= always。"),
   w("stabilize","verb","/ˈsteɪ.bə.laɪz/","使穩定","to make something steady","stabilize prices","stable → stabilize。"),
   w("hiatus","noun","/haɪˈeɪ.t̬əs/","中斷、空白期","a pause in an activity","after a long hiatus","a half-century hiatus 半世紀的空窗。"),
   w("sustained","adjective","/səˈsteɪnd/","持續的","continuing for a long time","sustained effort","a sustained presence 長期駐留。")],
  [gr("分詞構句 Hanging…","Hanging = Although it hangs，描述主詞狀態。","Hanging some 384,000 kilometers away, the Moon can seem like little more than a decorative feature"),
   gr("which is why","指前面整件事，引出結果。","which is why the same hemisphere perpetually faces us"),
   gr("比較 + might otherwise have been","與假設情況相比（否則可能會…）。","kept our climate more stable than it might otherwise have been")],
  [q("What does the writer suggest in the first paragraph?","The Moon matters more than it might seem","The Moon is only decorative","The Moon is very far away"),
   q("What does 'tidally locked' explain?","Why we always see the same side","Why the Moon glows","Why tides stopped"),
   q("What has happened since 1972, according to the text?","No one has set foot on the Moon","Crews visited every year","A base was built")]),
 L("How Coffee Conquered the World", "咖啡如何征服世界", [
   "Coffee's origin story is suitably energetic: an Ethiopian goat herder, the legend goes, noticed his flock prancing after nibbling the red fruit of a particular shrub. The tale is almost certainly apocryphal, but the first reliable records do point to the region, describing coffee being brewed in the Sufi monasteries of Yemen in the 15th century.",
   "From the Arabian Peninsula, the drink traveled along trade routes into the Ottoman Empire, where coffeehouses flourished, and then into Europe.",
   "There they acquired a reputation as hotbeds of conversation and commerce; some London coffeehouses evolved into institutions that still shape finance today. Authorities occasionally tried to suppress them, suspecting that so much animated discussion might breed dissent.",
   "Today, coffee ranks among the most valuable agricultural commodities, with Brazil far ahead as the leading producer. What we call beans are the seeds of coffee cherries, mostly from arabica and robusta plants. Their caffeine works by blocking adenosine, a molecule that accumulates during waking hours and signals fatigue, which explains why the morning cup feels so indispensable."],
  [w("suitably","adverb","/ˈsuː.t̬ə.bli/","恰如其分地","in a way that is right for the situation","suitably dressed","suitably energetic 恰好很有活力。"),
   w("apocryphal","adjective","/əˈpɑː.krə.fəl/","（故事）可疑的、杜撰的","probably not true, though often repeated","an apocryphal story","形容廣為流傳但可能是假的故事。"),
   w("flourish","verb","/ˈflɝː.ɪʃ/","蓬勃發展","to grow or develop successfully","Business flourished.","flourished 過去式。"),
   w("hotbed","noun","/ˈhɑːt.bed/","溫床","a place where a lot of an activity happens","a hotbed of new ideas","hotbeds of… …的溫床。"),
   w("animated","adjective","/ˈæn.ə.meɪ.t̬ɪd/","熱烈的、活躍的","full of interest and energy","an animated discussion","animated discussion 熱烈討論。"),
   w("dissent","noun","/dɪˈsent/","異議","strong disagreement with official ideas","political dissent","breed dissent 滋生異議。"),
   w("commodity","noun","/kəˈmɑː.də.t̬i/","商品、大宗物資","a product that is bought and sold","Oil is a valuable commodity.","agricultural commodities 農產品。"),
   w("accumulate","verb","/əˈkjuː.mjə.leɪt/","累積","to gradually increase in amount","Dust accumulates quickly.","accumulates 第三人稱單數。")],
  [gr("插入語 the legend goes","插在句中，表示「據傳說」。","an Ethiopian goat herder, the legend goes, noticed his flock prancing"),
   gr("強調助動詞 do point","do + 原形強調「確實」。","the first reliable records do point to the region"),
   gr("分詞構句 suspecting…","說明原因：因為懷疑…。","suspecting that so much animated discussion might breed dissent")],
  [q("How does the writer view the goat herder story?","Probably not true","Fully proven","Recently discovered"),
   q("Why did some authorities try to suppress coffeehouses?","They feared the discussions might lead to opposition","Coffee was too expensive","They preferred tea"),
   q("What does adenosine do, according to the text?","It builds up and signals tiredness","It makes coffee bitter","It grows coffee plants")]),
 L("The Underrated Power of a Walk", "被低估的散步力量", [
   "Of all the ways to improve one's health, walking is perhaps the least glamorous and the most overlooked. It demands no gym membership, no specialist kit and no particular skill, which may be precisely why it is so easily taken for granted.",
   "Even the much-quoted goal of 10,000 daily steps has humble commercial origins. It traces back to a 1960s Japanese marketing campaign for a pedometer, not to any clinical trial. More recent research suggests that substantial benefits accrue at considerably lower counts, and that any increase over a sedentary baseline is worthwhile.",
   "The rewards are wide-ranging. Brisk, regular walking improves cardiovascular fitness, helps regulate blood sugar and is associated with lower rates of depression.",
   "There is a cognitive dividend too. In a Stanford study, participants generated markedly more creative ideas while walking than while seated, an effect that lingered even after they sat back down. Philosophers from Aristotle to Nietzsche, it seems, were onto something when they did their best thinking on foot."],
  [w("overlooked","adjective","/ˌoʊ.vɚˈlʊkt/","被忽略的","not noticed or given attention","an overlooked detail","the most overlooked 最被忽略的。"),
   w("for granted","idiom (take… for granted)","/teɪk fɚ ˈɡræn.t̬ɪd/","視為理所當然","to not value something because it is always there","Don't take your health for granted.","被動：be taken for granted。"),
   w("humble","adjective","/ˈhʌm.bəl/","不起眼的、卑微的","simple and not special","humble beginnings","humble origins 不起眼的起源。"),
   w("accrue","verb","/əˈkruː/","累積（好處）","to increase gradually over time","Interest accrues daily.","benefits accrue 好處逐漸累積。"),
   w("sedentary","adjective","/ˈsed.ən.ter.i/","久坐的","involving a lot of sitting","a sedentary job","a sedentary baseline 久坐的基準。"),
   w("brisk","adjective","/brɪsk/","輕快的","quick and energetic","a brisk walk","brisk walking 快走。"),
   w("dividend","noun","/ˈdɪv.ə.dend/","紅利、好處","an extra benefit","a cognitive dividend","比喻額外收穫。"),
   w("markedly","adverb","/ˈmɑːr.kɪd.li/","顯著地","clearly and noticeably","markedly better","markedly more creative 明顯更有創意。")],
  [gr("Of all…, … is perhaps the least…","在所有…之中，…可能是最不…的。","Of all the ways to improve one's health, walking is perhaps the least glamorous and the most overlooked."),
   gr("trace back to","追溯到…。","It traces back to a 1960s Japanese marketing campaign for a pedometer"),
   gr("be onto something","發現了有價值的事。","Philosophers from Aristotle to Nietzsche, it seems, were onto something")],
  [q("Why might walking be taken for granted, according to the writer?","Because it needs no equipment or special skill","Because it is dangerous","Because it is expensive"),
   q("What does the writer say about the 10,000-step goal?","It came from marketing, not science","It was set by doctors","It is the minimum for any benefit"),
   q("What did the Stanford study suggest?","Walking boosted creativity even afterwards","Sitting improved memory","Walking reduced creativity")]),
 L("The Art of Being Heard", "讓人願意聽的說話藝術", [
   "Julian Treasure, who studies sound and communication, opens his TED talk with a question that will resonate with anyone who has been talked over in a meeting: why do some voices command attention while others are ignored?",
   "His answer starts with what he calls the deadly sins of speaking, habits that quietly erode a listener's goodwill. Gossip, judging, negativity, complaining, excuses, embellishment and dogmatism all make people tune out, regardless of how eloquent the speaker may be.",
   "As a counterweight, he proposes four foundations: honesty, authenticity, integrity and love, by which he means wishing people well.",
   "The second half turns to delivery. Treasure describes the voice as an instrument with a toolbox of its own, including register, timbre, prosody, pace, pitch and volume. Varying these deliberately, and using silence for emphasis, can transform how a message lands. He even leads the audience through a set of vocal warm-ups, a reminder that confident speaking is a skill to be practiced rather than a gift some people simply possess."],
  [w("command","verb","/kəˈmænd/","博得、引起（注意、尊重）","to deserve and get something such as attention or respect","She commands respect.","command attention 吸引注意。"),
   w("erode","verb","/ɪˈroʊd/","侵蝕、削弱","to gradually weaken or destroy","Trust eroded over time.","erode goodwill 消磨好感。"),
   w("embellishment","noun","/ɪmˈbel.ɪʃ.mənt/","誇大、潤飾","adding details to make a story more interesting, often untrue","the story without embellishment","embellish 的名詞。"),
   w("dogmatism","noun","/ˈdɑːɡ.mə.tɪ.zəm/","武斷、教條","insisting your opinions are right without considering others","political dogmatism","形容詞 dogmatic。"),
   w("eloquent","adjective","/ˈel.ə.kwənt/","口才好的","able to speak well and persuasively","an eloquent speech","how eloquent the speaker may be 不論多會說。"),
   w("counterweight","noun","/ˈkaʊn.t̬ɚ.weɪt/","平衡的力量","something that balances an opposing force","a counterweight to power","As a counterweight 作為抗衡。"),
   w("deliberately","adverb","/dɪˈlɪb.ɚ.ət.li/","刻意地","intentionally","She deliberately ignored me.","Varying these deliberately 刻意變化這些。"),
   w("possess","verb","/pəˈzes/","擁有","to have or own something","He possesses great talent.","possess a gift 擁有天賦。")],
  [gr("關係子句 who has been talked over","現在完成被動：曾被插話打斷的人。","anyone who has been talked over in a meeting"),
   gr("regardless of + 名詞子句","不論…。","regardless of how eloquent the speaker may be"),
   gr("rather than","而不是。","confident speaking is a skill to be practiced rather than a gift some people simply possess")],
  [q("What question does Treasure's talk begin with?","Why some voices get attention and others don't","How to sing well","How to write a speech"),
   q("What does he mean by 'love' as a foundation?","Wishing people well","Romantic feelings","Speaking loudly"),
   q("What is the message of the vocal warm-ups?","Confident speaking can be practiced","Only talented people can speak well","Silence should be avoided")]),
]
